impl Out for ATAlterConstraint {
    fn out(&self, s: &mut String) {
        s.push_str("ATALTERCONSTRAINT");
        self.fields(s, "");
    }

    fn fields(&self, s: &mut String, prefix: &str) {
        w::text(s, prefix, "conname", self.conname.as_deref());
        w::bool(s, prefix, "alterEnforceability", self.alterEnforceability);
        w::bool(s, prefix, "is_enforced", self.is_enforced);
        w::bool(s, prefix, "alterDeferrability", self.alterDeferrability);
        w::bool(s, prefix, "deferrable", self.deferrable);
        w::bool(s, prefix, "initdeferred", self.initdeferred);
        w::bool(s, prefix, "alterInheritability", self.alterInheritability);
        w::bool(s, prefix, "noinherit", self.noinherit);
    }
}

